#pragma once

// cxx-generated header for Rust types
#include "rust/cxx.h"

// trunk-recorder headers — these provide the real type definitions.
// Include paths are set by build.rs (gnuradio, boost, op25_repeater, etc.)
#include "trunk-recorder/plugin_manager/plugin_api.h"
#include "trunk-recorder/source.h"

namespace trunk_oxide {

// ── Shared enum/struct forward declarations (generated by cxx) ──
enum class TrSignalType : uint8_t;
enum class TrMessageType : uint8_t;
enum class TrState : uint8_t;
enum class TrMonitoringState : uint8_t;
enum class TrCallDataStatus : uint8_t;
struct TrPatchData;
struct TrTrunkMessage;
struct TrTransmission;
struct TrCallSource;
struct TrCallError;
struct TrCallData;
struct RustPluginBox;

// ── Opaque wrapper types that cxx sees ──
// These wrap raw pointers to trunk-recorder objects.

struct TrCall final {
    Call *ptr;
    explicit TrCall(Call *p) : ptr(p) {}
};

struct TrSystem final {
    System *ptr;
    explicit TrSystem(System *p) : ptr(p) {}
};

struct TrRecorder final {
    Recorder *ptr;
    explicit TrRecorder(Recorder *p) : ptr(p) {}
};

struct TrSource final {
    Source *ptr;
    explicit TrSource(Source *p) : ptr(p) {}
};

// ── Call accessor wrappers ──
int64_t call_get_talkgroup(const TrCall &call);
int64_t call_get_call_num(const TrCall &call);
int32_t call_get_sys_num(const TrCall &call);
double call_get_freq(const TrCall &call);
double call_get_signal(const TrCall &call);
double call_get_noise(const TrCall &call);
int32_t call_get_freq_error(const TrCall &call);
bool call_get_encrypted(const TrCall &call);
bool call_get_emergency(const TrCall &call);
bool call_get_is_analog(const TrCall &call);
bool call_is_conventional(const TrCall &call);
bool call_get_phase2_tdma(const TrCall &call);
int32_t call_get_tdma_slot(const TrCall &call);
int32_t call_get_priority(const TrCall &call);
bool call_get_mode(const TrCall &call);
bool call_get_duplex(const TrCall &call);
bool call_get_conversation_mode(const TrCall &call);
int64_t call_get_current_source_id(const TrCall &call);
double call_get_current_length(const TrCall &call);
int64_t call_get_start_time(const TrCall &call);
int64_t call_elapsed(const TrCall &call);
rust::String call_get_short_name(const TrCall &call);
rust::String call_get_talkgroup_display(const TrCall &call);
rust::String call_get_talkgroup_tag(const TrCall &call);
TrState call_get_state(const TrCall &call);
TrMonitoringState call_get_monitoring_state(const TrCall &call);

// ── System accessor wrappers ──
int32_t system_get_sys_num(const TrSystem &sys);
uint64_t system_get_sys_id(const TrSystem &sys);
rust::String system_get_short_name(const TrSystem &sys);
rust::String system_get_system_type(const TrSystem &sys);
uint64_t system_get_wacn(const TrSystem &sys);
uint64_t system_get_nac(const TrSystem &sys);
int32_t system_get_sys_rfss(const TrSystem &sys);
int32_t system_get_sys_site_id(const TrSystem &sys);
rust::String system_get_bandplan(const TrSystem &sys);
double system_get_analog_levels(const TrSystem &sys);
double system_get_digital_levels(const TrSystem &sys);
double system_get_squelch_db(const TrSystem &sys);
bool system_get_compress_wav(const TrSystem &sys);
bool system_get_conversation_mode(const TrSystem &sys);
int32_t system_get_message_count(const TrSystem &sys);
int32_t system_get_decode_rate(const TrSystem &sys);

// ── Recorder accessor wrappers ──
int32_t recorder_get_num(const TrRecorder &rec);
rust::String recorder_get_type_string(const TrRecorder &rec);
double recorder_get_freq(const TrRecorder &rec);
int32_t recorder_get_freq_error(const TrRecorder &rec);
int64_t recorder_get_talkgroup(const TrRecorder &rec);
int64_t recorder_get_wav_hz(const TrRecorder &rec);
bool recorder_is_analog(const TrRecorder &rec);
bool recorder_is_conventional(const TrRecorder &rec);
bool recorder_is_active(const TrRecorder &rec);
bool recorder_is_idle(const TrRecorder &rec);
double recorder_get_current_length(const TrRecorder &rec);

// ── Source accessor wrappers ──
int32_t source_get_num(const TrSource &src);
double source_get_center(const TrSource &src);
double source_get_rate(const TrSource &src);
double source_get_min_hz(const TrSource &src);
double source_get_max_hz(const TrSource &src);
rust::String source_get_driver(const TrSource &src);
rust::String source_get_device(const TrSource &src);
rust::String source_get_antenna(const TrSource &src);
double source_get_if_gain(const TrSource &src);
double source_get_lna_gain(const TrSource &src);
double source_get_pga_gain(const TrSource &src);
double source_get_vga1_gain(const TrSource &src);
double source_get_vga2_gain(const TrSource &src);
int32_t source_get_analog_recorder_count(const TrSource &src);
int32_t source_get_digital_recorder_count(const TrSource &src);
int32_t source_get_debug_recorder_count(const TrSource &src);
int32_t source_get_sigmf_recorder_count(const TrSource &src);

} // namespace trunk_oxide
